// คำนวณเดือนปัจจุบัน (Asia/Bangkok) + ชื่อไฟล์ + วันสุดท้ายของเดือน
// n8n default TZ = America/New_York -> ต้องบวก 7 ชม.เอง ไม่ใช้ $now
const bkk = new Date(Date.now() + 7*3600*1000);
const y = bkk.getUTCFullYear();
const m = bkk.getUTCMonth() + 1;              // 1-12
const mm = String(m).padStart(2,'0');

// วันสุดท้ายของเดือน: วันที่ 0 ของเดือนถัดไป = วันสุดท้ายเดือนนี้
const lastDay = new Date(Date.UTC(y, m, 0)).getUTCDate();   // m เป็น index เดือนถัดไปพอดี (getUTCMonth+1)
const lastDateStr = y + '-' + mm + '-' + String(lastDay).padStart(2,'0');  // YYYY-MM-DD ให้ USER_ENTERED ตีความเป็น date

const fileName = 'FM-DEM-032-038-61 | ใบตรวจเช็คเครื่องจักรประจําวัน | ' + mm + '-' + y;
const titleSuffix = mm + '-' + y;             // ใช้ค้นไฟล์ทีหลัง

return [{ json: {
  year: y, month: m, mm: mm,
  lastDay: lastDay, lastDate: lastDateStr,
  fileName: fileName, titleSuffix: titleSuffix,
  templateId: '1MdJXbrVhCC_oPO7TWH9HblgLAnJ6cWwJ1n7EhcqvfV4', destFolder: '1NQX4VupMsDTZredzc4YznbDIqsDcEpah'
}}];

// สร้าง payload batchUpdate: E3 + O4 = วันสุดท้ายของเดือน ทุกแท็บ
const info = $('คำนวณเดือน+ชื่อไฟล์+วันสุดท้าย').first().json;
const fileId = $json.id;                       // จาก Copy node
const lastDate = info.lastDate;                // YYYY-MM-DD

const TABS = [
  'FM-DEM-035_BSD72-1','FM-DEM-035_BSD72-2','FM-DEM-036_SP100-1','FM-DEM-036_SP100-2',
  'FM-DEM-037_BOOSTER NO.1','FM-DEM-037_BOOSTER NO.2','FM-DEM-037_BOOSTER NO.3',
  'FM-DEM-038_COOLING 1','FM-DEM-038_COOLING 2','FM-DEM-038_COOLING 3','FM-DEM-038_COOLING 5',
  'FM-DEM-032_ASB250-3','FM-DEM-033_PF8-3','FM-DEM-033_PF8-5','FM-DEM-033_PF8-6',
  'FM-DEM-033_PF8-7','FM-DEM-033_PF8-8','FM-DEM-061_TE'
];

const data = [];
for (const tab of TABS) {
  data.push({ range: "'"+tab+"'!E3", values: [[lastDate]] });
  data.push({ range: "'"+tab+"'!O4", values: [[lastDate]] });
}

return [{ json: {
  fileId: fileId,
  fileName: info.fileName,
  body: { valueInputOption: 'USER_ENTERED', data: data }
}}];
